import{z as A,x as d,o as r,c as B,q as E,j as t,D as l,d as s,s as n,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"Flush+Reload","description":"","frontmatter":{"title":"Flush+Reload","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/flush-reload.md","filePath":"cs/flush-reload.md","lastUpdated":1791063341000}'),h={name:"cs/flush-reload.md"};function p(m,a,u,c,f,D){const o=d("Mermaid");return r(),B("div",null,[a[2]||(a[2]=E('<h1 id="flush-reload" tabindex="-1">Flush+Reload <a class="header-anchor" href="#flush-reload" aria-label="Permalink to &quot;Flush+Reload&quot;">​</a></h1><div class="epigraph"><p>共享页（含共享库）上，驱逐再等待再测加载时间，可推断别人是否访问了该行。这是缓存侧信道的经典形状：共享是特性，也是通道。</p><footer>—— Yarom and Falkner, Flush+Reload, USENIX Security 2014</footer></div><p>上一课<a href="/cs/rowhammer-mitigations">Rowhammer</a>扰动的是存储比特；本课缺口是<strong>把共享缓存当通道</strong>。主干侧信道课已警告过时间泄漏；这里点名 Flush+Reload 作为该类机制的具名代表，不给测密钥的实验步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内存去重（dedup）与共享 libc 让不同进程物理共享同一缓存行——共享是省内存的特性，也把「谁访问过这一行」变成可观测信号。攻击者把共享行驱逐出缓存，等受害者可能访问，再重新加载并计时：缓存命中（几十纳秒）与回内存取回（上百纳秒以上）的差距一眼可辨，这只需要一台高分辨率计时器。缺口是对策清单：禁共享页、降计时精度、密码学常数时间化、敏感计算核隔离。</p><p><span class="marginnote">给个数字感受一下差距：一次缓存命中约 40 纳秒，回内存取数约 200-300 纳秒，差出 5 倍以上。这两个数都远小于一次系统调用（微秒级），所以「加载一行代码并掐表」完全可以藏在正常程序运行里，日志上看不出任何异常。</span></p><h3 id="云共驻" tabindex="-1">云共驻 <a class="header-anchor" href="#云共驻" aria-label="Permalink to &quot;云共驻&quot;">​</a></h3><p>云上同主机的租户就是模型里的观察者：页去重一开，跨虚拟机的共享行天然存在，观察不需要任何越界访问。</p><p><span class="marginnote">Yarom–Falkner 2014。禁止还原密钥的实验指导。VM 逃逸下一课换隔离边界。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把「共享加计时」这条通道陈述完整，再逐条配对策：关页去重，把共享库从高价值进程拆开，计时器降精度加抖动，密码学写成无分支无密钥查表的常数时间，敏感计算钉上隔离核。下一课虚拟机逃逸：那是逻辑边界被穿，不是缓存被测。</p>',12)),(r(),t(i,null,{default:l(()=>[n(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHARE%5B%22%E5%85%B1%E4%BA%AB%E8%A1%8C%22%5D%20--%3E%20FLUSH%5B%22%E9%A9%B1%E9%80%90%22%5D%0A%20%20FLUSH%20--%3E%20TIME%5B%22%E5%86%8D%E5%8A%A0%E8%BD%BD%E8%AE%A1%E6%97%B6%22%5D%0A%20%20TIME%20--%3E%20INF%5B%22%E6%8E%A8%E6%96%AD%E4%BB%96%E4%BA%BA%E8%AE%BF%E9%97%AE%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"机制一句话：控制流可经缓存泄漏——受害者的分支走向决定它触碰哪些共享行，攻击者逐行计时就把秘密位读了出来；命中与未命中之间数倍的延迟差是通道的载波。这也是 Spectre 类攻击的读出口。VM 逃逸下一课是完整性：从客机到宿主机。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"可以把它想象成图书馆查岗：攻击者把某几本书全部搬走（flush），过一会儿再去看哪些书回到了原位——回到了，说明这段时间有人借阅过。书的内容一个字没看，但「谁碰过哪本」这个事实本身就把受害者的秘密漏了出来。")],-1)),(r(),t(i,null,{default:l(()=>[n(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20S%5B%22%E7%A7%98%E5%AF%86%E4%BD%8D%20b%3D0%20%E6%88%96%201%22%5D%20--%3E%20BR%7B%22%E5%8F%97%E5%AE%B3%E8%80%85%E7%9A%84%E5%88%86%E6%94%AF%22%7D%0A%20%20BR%20--%20%22b%3D0%22%20--%3E%20L0%5B%22%E8%A7%A6%E7%A2%B0%E5%85%B1%E4%BA%AB%E8%A1%8C%20A%22%5D%0A%20%20BR%20--%20%22b%3D1%22%20--%3E%20L1%5B%22%E8%A7%A6%E7%A2%B0%E5%85%B1%E4%BA%AB%E8%A1%8C%20B%22%5D%0A%20%20L0%20--%3E%20C%5B%22%E8%A1%8C%20A%20%E7%95%99%E5%9C%A8%E7%BC%93%E5%AD%98%2CB%20%E8%A2%AB%E9%A9%B1%E9%80%90%22%5D%0A%20%20L1%20--%3E%20C%0A%20%20C%20--%3E%20M%5B%22%E6%94%BB%E5%87%BB%E8%80%85%E9%80%90%E8%A1%8C%20reload%20%E8%AE%A1%E6%97%B6%22%5D%0A%20%20M%20--%3E%20R%7B%22%E5%93%AA%E8%A1%8C%E5%BF%AB%3F%22%7D%0A%20%20R%20--%20%22A%20%E5%BF%AB%22%20--%3E%20G0%5B%22%E6%8E%A8%E6%96%AD%20b%3D0%22%5D%0A%20%20R%20--%20%22B%20%E5%BF%AB%22%20--%3E%20G1%5B%22%E6%8E%A8%E6%96%AD%20b%3D1%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=E('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写测量配方——不给阈值、不给探针排布。边界要点名：对策没有单发银弹，降计时精度会被多次采样平均绕回，禁共享则付出内存与启动时间。虚拟机逃逸下一课。</p><p><span class="marginnote">初学者容易以为「把计时器精度降到 100ns 就安全了」。实际上攻击者可以让同一操作重复上万次、把带噪声的读数取平均——单个样本分不出 40ns 和 200ns，一万次平均后差距照样浮现。这就是为什么降精度只能抬门槛，必须配合常数时间才行。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Rowhammer 翻比特；Flush+Reload 测共享行时间。</li><li>共享库与去重是通道来源。</li><li>常数时间与隔离是对策。</li><li>下一课 VM 逃逸。</li><li>出处：Yarom and Falkner, 2014；<a href="/cs/side-channel">side-channel</a>。</li></ul>',5))])}const F=A(h,[["render",p]]);export{b as __pageData,F as default};
